begin;

create or replace function public.get_trial_balance(p_organization_id uuid,p_period_id uuid)
returns jsonb language plpgsql security definer set search_path=''
as $$ declare v_period record; v_rows jsonb; v_row_count integer; v_total_debit bigint; v_total_credit bigint; v_total_opening bigint; v_total_closing bigint;
begin
if auth.uid() is null or not public.has_org_permission(p_organization_id,'screen.trial_balance.view') or not public.has_org_permission(p_organization_id,'trial_balance.view') then raise exception 'Not authorized'; end if;
select id,organization_id,period_start,period_end,status into v_period from public.financial_periods where id=p_period_id and organization_id=p_organization_id; if v_period.id is null then raise exception 'Financial period not found'; end if;
with scoped as (select ff.account_id,ff.financial_period_id,coalesce(ff.debit_minor,case when ff.amount_minor>0 then ff.amount_minor else 0 end) debit_minor,coalesce(ff.credit_minor,case when ff.amount_minor<0 then -ff.amount_minor else 0 end) credit_minor from public.financial_facts ff where ff.organization_id=p_organization_id and ff.fact_type='actual' and public.has_org_data_scope(ff.organization_id,'legal_entity',ff.legal_entity_id) and public.has_org_data_scope(ff.organization_id,'branch',ff.branch_id) and public.has_org_data_scope(ff.organization_id,'department',ff.department_id) and public.has_org_data_scope(ff.organization_id,'cost_center',ff.cost_center_id) and public.has_org_data_scope(ff.organization_id,'region',ff.region_id) and public.has_org_data_scope(ff.organization_id,'product',ff.product_id) and public.has_org_data_scope(ff.organization_id,'project',ff.project_id)), ap as (select a.id account_id,a.code,a.name,a.account_type,a.statement_type,a.statement_section,coalesce(sum(case when fp.period_start<v_period.period_start then s.debit_minor-s.credit_minor else 0 end),0)::bigint opening_balance,coalesce(sum(case when fp.id=p_period_id then s.debit_minor else 0 end),0)::bigint period_debit,coalesce(sum(case when fp.id=p_period_id then s.credit_minor else 0 end),0)::bigint period_credit from public.accounts a join scoped s on s.account_id=a.id join public.financial_periods fp on fp.id=s.financial_period_id and fp.organization_id=p_organization_id where a.organization_id=p_organization_id group by a.id,a.code,a.name,a.account_type,a.statement_type,a.statement_section), fr as (select *,opening_balance+period_debit-period_credit closing_balance from ap where opening_balance<>0 or period_debit<>0 or period_credit<>0) select count(*),coalesce(sum(period_debit),0),coalesce(sum(period_credit),0),coalesce(sum(opening_balance),0),coalesce(sum(closing_balance),0),coalesce(jsonb_agg(to_jsonb(fr) order by code),'[]'::jsonb) into v_row_count,v_total_debit,v_total_credit,v_total_opening,v_total_closing,v_rows from fr;
return jsonb_build_object('organization_id',p_organization_id,'period_id',v_period.id,'period_start',v_period.period_start,'period_end',v_period.period_end,'period_status',v_period.status,'row_count',v_row_count,'total_period_debit',v_total_debit,'total_period_credit',v_total_credit,'period_difference',v_total_debit-v_total_credit,'total_opening_balance',v_total_opening,'total_closing_balance',v_total_closing,'rows',v_rows); end; $$;

create or replace function public.get_dimension_analysis(p_organization_id uuid,p_period_id uuid,p_dimension text)
returns jsonb language plpgsql security definer set search_path=''
as $$ declare v_period record; v_dimension text:=lower(trim(coalesce(p_dimension,''))); v_rows jsonb;
begin
if auth.uid() is null or not public.has_org_permission(p_organization_id,'screen.dimensions.view') or not public.has_org_permission(p_organization_id,'dimensions.view') then raise exception 'Not authorized'; end if;
select id,organization_id,period_start,period_end,status into v_period from public.financial_periods where id=p_period_id and organization_id=p_organization_id; if v_period.id is null then raise exception 'Financial period not found'; end if;
if v_dimension not in ('branch','cost_center') then raise exception 'Unsupported dimension'; end if;
if v_dimension='branch' then
select coalesce(jsonb_agg(x order by x.revenue desc),'[]'::jsonb) into v_rows from (select coalesce(b.name,'غير محدد') dimension_name,b.id dimension_id,coalesce(sum(case when lower(coalesce(a.account_type,'')) in ('revenue','income') then ff.credit_minor-ff.debit_minor else 0 end),0)::bigint revenue,coalesce(sum(case when lower(coalesce(a.account_type,'')) in ('cost_of_sales','cogs') then ff.debit_minor-ff.credit_minor else 0 end),0)::bigint cogs,coalesce(sum(case when lower(coalesce(a.account_type,'')) in ('expense','operating_expense','operating_expenses') then ff.debit_minor-ff.credit_minor else 0 end),0)::bigint operating_expenses from public.financial_facts ff join public.accounts a on a.id=ff.account_id and a.organization_id=p_organization_id left join public.branches b on b.id=ff.branch_id and b.organization_id=p_organization_id where ff.organization_id=p_organization_id and ff.financial_period_id=p_period_id and ff.fact_type='actual' and public.has_org_data_scope(ff.organization_id,'legal_entity',ff.legal_entity_id) and public.has_org_data_scope(ff.organization_id,'branch',ff.branch_id) and public.has_org_data_scope(ff.organization_id,'department',ff.department_id) and public.has_org_data_scope(ff.organization_id,'cost_center',ff.cost_center_id) and public.has_org_data_scope(ff.organization_id,'region',ff.region_id) and public.has_org_data_scope(ff.organization_id,'product',ff.product_id) and public.has_org_data_scope(ff.organization_id,'project',ff.project_id) group by b.id,b.name) x;
else
select coalesce(jsonb_agg(x order by x.revenue desc),'[]'::jsonb) into v_rows from (select coalesce(cc.name,'غير محدد') dimension_name,cc.id dimension_id,coalesce(sum(case when lower(coalesce(a.account_type,'')) in ('revenue','income') then ff.credit_minor-ff.debit_minor else 0 end),0)::bigint revenue,coalesce(sum(case when lower(coalesce(a.account_type,'')) in ('cost_of_sales','cogs') then ff.debit_minor-ff.credit_minor else 0 end),0)::bigint cogs,coalesce(sum(case when lower(coalesce(a.account_type,'')) in ('expense','operating_expense','operating_expenses') then ff.debit_minor-ff.credit_minor else 0 end),0)::bigint operating_expenses from public.financial_facts ff join public.accounts a on a.id=ff.account_id and a.organization_id=p_organization_id left join public.cost_centers cc on cc.id=ff.cost_center_id and cc.organization_id=p_organization_id where ff.organization_id=p_organization_id and ff.financial_period_id=p_period_id and ff.fact_type='actual' and public.has_org_data_scope(ff.organization_id,'legal_entity',ff.legal_entity_id) and public.has_org_data_scope(ff.organization_id,'branch',ff.branch_id) and public.has_org_data_scope(ff.organization_id,'department',ff.department_id) and public.has_org_data_scope(ff.organization_id,'cost_center',ff.cost_center_id) and public.has_org_data_scope(ff.organization_id,'region',ff.region_id) and public.has_org_data_scope(ff.organization_id,'product',ff.product_id) and public.has_org_data_scope(ff.organization_id,'project',ff.project_id) group by cc.id,cc.name) x;
end if;
return jsonb_build_object('organization_id',p_organization_id,'period',jsonb_build_object('id',v_period.id,'start',v_period.period_start,'end',v_period.period_end,'status',v_period.status),'dimension',v_dimension,'rows',v_rows,'methodology',jsonb_build_object('source','published actual financial facts','ai_authoritative',false)); end; $$;

create or replace function public.get_scenario_results(p_organization_id uuid,p_scenario_id uuid)
returns jsonb language plpgsql security definer set search_path=''
as $$ declare v_s record; v_base record; v_rows jsonb; v_metrics jsonb;
begin
if auth.uid() is null or not public.has_org_permission(p_organization_id,'screen.scenarios.view') or not public.has_org_permission(p_organization_id,'scenario.run') then raise exception 'Not authorized'; end if;
select s.id,s.organization_id,s.name,s.description,s.scenario_type,s.status,s.base_version_id into v_s from public.planning_scenarios s where s.id=p_scenario_id and s.organization_id=p_organization_id; if v_s.id is null then raise exception 'Scenario not found'; end if; if v_s.base_version_id is null then raise exception 'Scenario base version is required'; end if;
select pv.id,pv.name,pv.version_type,pv.status into v_base from public.planning_versions pv where pv.id=v_s.base_version_id and pv.organization_id=p_organization_id; if v_base.id is null then raise exception 'Base planning version not found'; end if;
with base_lines as (select l.financial_period_id,l.account_id,sum(l.amount_minor)::numeric base_minor from (select b.financial_period_id,b.account_id,b.amount_minor from public.budget_lines b where b.organization_id=p_organization_id and b.planning_version_id=v_base.id and v_base.version_type='budget' union all select f.financial_period_id,f.account_id,f.amount_minor from public.forecast_lines f where f.organization_id=p_organization_id and f.planning_version_id=v_base.id and v_base.version_type='forecast') l group by l.financial_period_id,l.account_id), adjusted as (select bl.financial_period_id,bl.account_id,bl.base_minor,coalesce(sum(case when sa.adjustment_type='absolute' then sa.adjustment_value*100 when sa.adjustment_type='percentage' then bl.base_minor*(sa.adjustment_value/100) else 0 end),0)::numeric delta_minor from base_lines bl left join public.scenario_adjustments sa on sa.scenario_id=p_scenario_id and sa.financial_period_id=bl.financial_period_id and sa.account_id=bl.account_id group by bl.financial_period_id,bl.account_id,bl.base_minor), calculated as (select a.financial_period_id,a.account_id,a.base_minor,round(a.base_minor+a.delta_minor)::bigint scenario_minor,round(a.delta_minor)::bigint delta_minor from adjusted a), account_rows as (select c.financial_period_id,c.account_id,acc.code,acc.name,acc.account_type,acc.statement_section,c.base_minor,c.delta_minor,c.scenario_minor from calculated c join public.accounts acc on acc.id=c.account_id and acc.organization_id=p_organization_id), metrics as (select coalesce(sum(case when lower(coalesce(account_type,'')) in ('revenue','income') then scenario_minor else 0 end),0)::bigint revenue,coalesce(sum(case when lower(coalesce(account_type,'')) in ('cost_of_sales','cogs') then scenario_minor else 0 end),0)::bigint cogs,coalesce(sum(case when lower(coalesce(account_type,'')) in ('expense','operating_expense','operating_expenses') then scenario_minor else 0 end),0)::bigint operating_expenses,coalesce(sum(case when lower(coalesce(account_type,'')) in ('finance_cost','finance_expense') then scenario_minor else 0 end),0)::bigint finance_cost,coalesce(sum(case when lower(coalesce(account_type,'')) in ('tax','income_tax') then scenario_minor else 0 end),0)::bigint tax,coalesce(sum(case when lower(coalesce(account_type,'')) in ('revenue','income') then base_minor else 0 end),0)::bigint base_revenue,coalesce(sum(case when lower(coalesce(account_type,'')) in ('cost_of_sales','cogs') then base_minor else 0 end),0)::bigint base_cogs,coalesce(sum(case when lower(coalesce(account_type,'')) in ('expense','operating_expense','operating_expenses') then base_minor else 0 end),0)::bigint base_opex from account_rows) select coalesce(jsonb_agg(jsonb_build_object('period_id',ar.financial_period_id,'account_id',ar.account_id,'code',ar.code,'name',ar.name,'account_type',ar.account_type,'base',ar.base_minor,'adjustment',ar.delta_minor,'scenario',ar.scenario_minor) order by ar.financial_period_id,ar.code),'[]'::jsonb) into v_rows from account_rows ar;
select jsonb_build_object('base_revenue',m.base_revenue,'scenario_revenue',m.revenue,'base_cogs',m.base_cogs,'scenario_cogs',m.cogs,'base_gross_profit',m.base_revenue-m.base_cogs,'scenario_gross_profit',m.revenue-m.cogs,'base_operating_expenses',m.base_opex,'scenario_operating_expenses',m.operating_expenses,'base_ebitda',m.base_revenue-m.base_cogs-m.base_opex,'scenario_ebitda',m.revenue-m.cogs-m.operating_expenses,'scenario_finance_cost',m.finance_cost,'scenario_tax',m.tax,'scenario_net_income',m.revenue-m.cogs-m.operating_expenses-m.finance_cost-m.tax) into v_metrics from metrics m;
return jsonb_build_object('scenario',jsonb_build_object('id',v_s.id,'name',v_s.name,'description',v_s.description,'type',v_s.scenario_type,'status',v_s.status),'base_version',jsonb_build_object('id',v_base.id,'name',v_base.name,'type',v_base.version_type,'status',v_base.status),'metrics',v_metrics,'rows',v_rows); end; $$;

create or replace function public.get_variance_analysis(p_organization_id uuid,p_period_id uuid,p_budget_version_id uuid,p_forecast_version_id uuid default null)
returns jsonb language plpgsql security definer set search_path=''
as $$ declare v_result jsonb;
begin
if auth.uid() is null or not public.has_org_permission(p_organization_id,'screen.variance.view') or not public.has_org_permission(p_organization_id,'variance.view') then raise exception 'forbidden'; end if;
if not exists(select 1 from public.financial_periods where id=p_period_id and organization_id=p_organization_id) then raise exception 'invalid period'; end if;
if not exists(select 1 from public.planning_versions where id=p_budget_version_id and organization_id=p_organization_id and version_type='budget' and status='approved') then raise exception 'budget version must be approved'; end if;
if p_forecast_version_id is not null and not exists(select 1 from public.planning_versions where id=p_forecast_version_id and organization_id=p_organization_id and version_type='forecast' and status='approved') then raise exception 'forecast version must be approved'; end if;
with actuals as (select ff.account_id,sum(ff.amount_minor)::bigint amount_minor from public.financial_facts ff where ff.organization_id=p_organization_id and ff.financial_period_id=p_period_id and ff.status='published' and public.has_org_data_scope(ff.organization_id,'legal_entity',ff.legal_entity_id) and public.has_org_data_scope(ff.organization_id,'branch',ff.branch_id) and public.has_org_data_scope(ff.organization_id,'department',ff.department_id) and public.has_org_data_scope(ff.organization_id,'cost_center',ff.cost_center_id) and public.has_org_data_scope(ff.organization_id,'region',ff.region_id) and public.has_org_data_scope(ff.organization_id,'product',ff.product_id) and public.has_org_data_scope(ff.organization_id,'project',ff.project_id) group by ff.account_id), budget as (select bl.account_id,sum(bl.amount_minor)::bigint amount_minor from public.budget_lines bl where bl.organization_id=p_organization_id and bl.planning_version_id=p_budget_version_id and bl.financial_period_id=p_period_id group by bl.account_id), forecast as (select fl.account_id,sum(fl.amount_minor)::bigint amount_minor from public.forecast_lines fl where fl.organization_id=p_organization_id and fl.planning_version_id=p_forecast_version_id and fl.financial_period_id=p_period_id group by fl.account_id), rows as (select a.id account_id,a.code,a.name,a.account_type,coalesce(x.amount_minor,0)::bigint actual_minor,coalesce(b.amount_minor,0)::bigint budget_minor,coalesce(f.amount_minor,0)::bigint forecast_minor from public.accounts a left join actuals x on x.account_id=a.id left join budget b on b.account_id=a.id left join forecast f on f.account_id=a.id where a.organization_id=p_organization_id and (x.account_id is not null or b.account_id is not null or f.account_id is not null)), m as (select coalesce(sum(actual_minor) filter(where lower(account_type) in ('revenue','income','sales')),0)::bigint ar,coalesce(sum(budget_minor) filter(where lower(account_type) in ('revenue','income','sales')),0)::bigint br,coalesce(sum(forecast_minor) filter(where lower(account_type) in ('revenue','income','sales')),0)::bigint fr,coalesce(sum(actual_minor) filter(where lower(account_type) in ('cogs','cost_of_sales')),0)::bigint ac,coalesce(sum(budget_minor) filter(where lower(account_type) in ('cogs','cost_of_sales')),0)::bigint bc,coalesce(sum(forecast_minor) filter(where lower(account_type) in ('cogs','cost_of_sales')),0)::bigint fc,coalesce(sum(actual_minor) filter(where lower(account_type) in ('opex','operating_expense')),0)::bigint ao,coalesce(sum(budget_minor) filter(where lower(account_type) in ('opex','operating_expense')),0)::bigint bo,coalesce(sum(forecast_minor) filter(where lower(account_type) in ('opex','operating_expense')),0)::bigint fo from rows) select jsonb_build_object('period_id',p_period_id,'budget_version_id',p_budget_version_id,'forecast_version_id',p_forecast_version_id,'rows',coalesce((select jsonb_agg(jsonb_build_object('account_id',account_id,'code',code,'name',name,'account_type',account_type,'actual_minor',actual_minor,'budget_minor',budget_minor,'forecast_minor',forecast_minor,'variance_vs_budget_minor',actual_minor-budget_minor,'variance_vs_forecast_minor',case when p_forecast_version_id is null then null else actual_minor-forecast_minor end,'variance_vs_budget_pct',case when budget_minor=0 then null else round(((actual_minor-budget_minor)::numeric/abs(budget_minor))*100,2) end) order by code) from rows),'[]'::jsonb),'metrics',(select jsonb_build_object('revenue',jsonb_build_object('actual_minor',ar,'budget_minor',br,'forecast_minor',fr,'variance_vs_budget_minor',ar-br,'variance_vs_forecast_minor',case when p_forecast_version_id is null then null else ar-fr end),'cogs',jsonb_build_object('actual_minor',ac,'budget_minor',bc,'forecast_minor',fc,'variance_vs_budget_minor',ac-bc,'variance_vs_forecast_minor',case when p_forecast_version_id is null then null else ac-fc end),'gross_profit',jsonb_build_object('actual_minor',ar-ac,'budget_minor',br-bc,'forecast_minor',fr-fc,'variance_vs_budget_minor',(ar-ac)-(br-bc),'variance_vs_forecast_minor',case when p_forecast_version_id is null then null else (ar-ac)-(fr-fc) end),'opex',jsonb_build_object('actual_minor',ao,'budget_minor',bo,'forecast_minor',fo,'variance_vs_budget_minor',ao-bo,'variance_vs_forecast_minor',case when p_forecast_version_id is null then null else ao-fo end),'ebitda',jsonb_build_object('actual_minor',ar-ac-ao,'budget_minor',br-bc-bo,'forecast_minor',fr-fc-fo,'variance_vs_budget_minor',(ar-ac-ao)-(br-bc-bo),'variance_vs_forecast_minor',case when p_forecast_version_id is null then null else (ar-ac-ao)-(fr-fc-fo) end)) from m)) into v_result;
return v_result; end; $$;

revoke execute on function public.get_trial_balance(uuid,uuid),public.get_dimension_analysis(uuid,uuid,text),public.get_scenario_results(uuid,uuid),public.get_variance_analysis(uuid,uuid,uuid,uuid) from anon,public;
grant execute on function public.get_trial_balance(uuid,uuid),public.get_dimension_analysis(uuid,uuid,text),public.get_scenario_results(uuid,uuid),public.get_variance_analysis(uuid,uuid,uuid,uuid) to authenticated;

commit;
